create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,phone text not null,role text not null check(role in('customer','collector','admin')),created_at timestamptz not null default now());
create table if not exists public.pickup_requests(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.profiles(id) on delete cascade,collector_id uuid references public.profiles(id) on delete set null,material text not null,location text not null,latitude double precision,longitude double precision,pickup_type text not null default 'Instant' check(pickup_type in('Instant','Scheduled')),status text not null default 'Pending' check(status in('Pending','Accepted','Completed','Cancelled')),created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.waste_records(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,material text not null,kg numeric(12,2) not null check(kg>0),points integer not null default 0,created_at timestamptz not null default now());
create table if not exists public.payment_intents(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,service text not null,method text not null,account_reference text not null,amount_zmw numeric(12,2) not null check(amount_zmw>0),status text not null default 'Pending',provider_reference text,created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.pickup_requests enable row level security;alter table public.waste_records enable row level security;alter table public.payment_intents enable row level security;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,phone,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','DOTI User'),coalesce(new.raw_user_meta_data->>'phone',''),case when new.raw_user_meta_data->>'role'='collector' then 'collector' else 'customer' end);return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create policy "profile read" on public.profiles for select using(auth.uid()=id or exists(select 1 from public.profiles a where a.id=auth.uid() and a.role='admin'));
create policy "profile update" on public.profiles for update using(auth.uid()=id) with check(auth.uid()=id);
create policy "pickup insert" on public.pickup_requests for insert with check(auth.uid()=customer_id);
create policy "pickup read" on public.pickup_requests for select using(auth.uid()=customer_id or auth.uid()=collector_id or exists(select 1 from public.profiles a where a.id=auth.uid() and a.role='admin'));
create policy "pickup update" on public.pickup_requests for update using(exists(select 1 from public.profiles a where a.id=auth.uid() and a.role in('collector','admin')));
create policy "waste insert" on public.waste_records for insert with check(auth.uid()=user_id);
create policy "waste read" on public.waste_records for select using(auth.uid()=user_id or exists(select 1 from public.profiles a where a.id=auth.uid() and a.role='admin'));
create policy "payment insert" on public.payment_intents for insert with check(auth.uid()=user_id);
create policy "payment read" on public.payment_intents for select using(auth.uid()=user_id or exists(select 1 from public.profiles a where a.id=auth.uid() and a.role='admin'));
